import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;
import java.util.logging.*;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Template cache for report generation
    private static final Map<String, String> REPORT_TEMPLATES = new HashMap<>();
    static {
        REPORT_TEMPLATES.put("summary", "SELECT id, name, total FROM orders WHERE region = '${region}' AND quarter = '${quarter}'");
        REPORT_TEMPLATES.put("detail", "SELECT * FROM order_details WHERE order_id IN (SELECT id FROM orders WHERE region = '${region}' AND status = '${status}')");
        REPORT_TEMPLATES.put("audit", "SELECT u.name, a.action, a.timestamp FROM audit_log a JOIN users u ON a.user_id = u.id WHERE a.module = '${module}'");
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL") != null ? System.getenv("JDBC_URL") : "jdbc:postgresql://db:5432/reports";
        String user = System.getenv("DB_USER") != null ? System.getenv("DB_USER") : "report_svc";
        String pass = System.getenv("DB_PASS") != null ? System.getenv("DB_PASS") : "";
        return DriverManager.getConnection(url, user, pass);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String templateName = req.getParameter("template");
        String format = req.getParameter("format");

        if (templateName == null || !REPORT_TEMPLATES.containsKey(templateName)) {
            resp.sendError(400, "Invalid template");
            return;
        }

        String sqlTemplate = REPORT_TEMPLATES.get(templateName);

        // Collect all substitution parameters from request
        Map<String, String> params = new HashMap<>();
        Enumeration<String> paramNames = req.getParameterNames();
        while (paramNames.hasMoreElements()) {
            String name = paramNames.nextElement();
            if (!name.equals("template") && !name.equals("format")) {
                String value = req.getParameter(name);
                // Basic sanitization - remove obvious SQL keywords
                if (value != null) {
                    value = value.replaceAll("(?i)(DROP|ALTER|TRUNCATE)\\s", "");
                }
                params.put(name, value);
            }
        }

        // Substitute parameters into SQL template
        StringSubstitutor sub = new StringSubstitutor(params);
        String finalSql = sub.replace(sqlTemplate);

        log.info("Executing report query: " + finalSql);

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalSql)) {

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Custom report - accepts raw SQL for admin users
        String role = (String) req.getAttribute("userRole");
        if (!"admin".equals(role)) {
            resp.sendError(403, "Admin only");
            return;
        }
        String customSql = req.getReader().lines().reduce("", String::concat);
        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(customSql)) {
            // ... same output logic
            resp.setStatus(200);
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }
}
